"""The admitted set is exactly {G o pi}: every map from centered rows to the simplex.

(a) Universal constructor. factor(G)(x) = G(x - rowmax(x)). For 24 seeded, deliberately
    arbitrary G (random linear maps into softmax, power laws, constant simplex vectors, mixtures,
    permutations, tanh-normalizers) every kernel is admitted by the bundle and rejected by the
    reference arm and by the completed arm.
(b) Two-sided closure. The admitted set is closed under pre-composition with any map s that
    respects per-row shift classes (scaling, negation, column permutation, any function of the
    centered row) and under post-composition with any simplex-preserving map Phi (smoothing,
    column reversal, power-renormalization, row rolling). Wrapping the REFERENCE either way
    yields an admitted wrong kernel.
Writes results/characterization.json.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(HERE))
import gate  # noqa: E402

REF = gate.reference()


def rowmax_center(x):
    w = np.asarray(x, dtype=np.float64)
    return w - np.max(w, axis=-1, keepdims=True)


def normalize(w):
    return w / np.sum(w, axis=-1, keepdims=True)


def softmax64(z):
    return normalize(np.exp(z - np.max(z, axis=-1, keepdims=True)))


def factor(G):
    """The universal constructor: any G from centered rows to the simplex gives an admitted kernel."""

    def softmax(x):
        return np.asarray(G(rowmax_center(x)), dtype=np.float64).astype(x.dtype)

    return softmax


def random_G(seed: int):
    kind = seed % 6
    rng_seed = 1000 + seed

    def G(z):
        n = z.shape[-1]
        rng = np.random.default_rng([rng_seed, n])  # deterministic per (seed, n): a function of z
        if kind == 0:  # softmax of a random affine map of the centered row
            A = rng.normal(size=(n, n)) / np.sqrt(n)
            b = rng.normal(size=(n,))
            return softmax64(z @ A.T + b)
        if kind == 1:  # power law of the gap to the max
            p = rng.uniform(0.5, 4.0)
            return normalize((1.0 - z) ** (-p))  # z <= 0 so 1 - z >= 1
        if kind == 2:  # constant random simplex vector (ignores z)
            v = rng.dirichlet(np.ones(n))
            return np.broadcast_to(v, z.shape).copy()
        if kind == 3:  # mixture of softmax and a random constant vector
            v = rng.dirichlet(np.ones(n))
            a = rng.uniform(0.1, 0.9)
            return a * softmax64(z) + (1 - a) * v
        if kind == 4:  # softmax of a fixed random column permutation of the centered row
            perm = rng.permutation(n)
            return softmax64(z[..., perm])
        # kind == 5: tanh-squashed normalizer
        return normalize(np.tanh(z) + 1.0 + 1e-3)

    return G


# (b) pre-composition maps s: respect per-row shift classes (s(x + c) = s(x) + c').
def pre_scale(t):
    return lambda x: t * x


def pre_negate(x):
    return -x


def pre_permute_columns(x):
    n = x.shape[-1]
    perm = np.random.default_rng(n).permutation(n)
    return x[..., perm]


def pre_tanh_of_centered(x):
    return np.tanh(rowmax_center(x))


def pre_cube_of_centered(x):
    return rowmax_center(x) ** 3


# post-composition maps Phi: simplex -> simplex.
def post_smooth(y):
    return 0.9 * y + 0.1 / y.shape[-1]


def post_reverse(y):
    return y[..., ::-1]


def post_square_renorm(y):
    return normalize(y * y)


def post_sqrt_renorm(y):
    return normalize(np.sqrt(y))


def post_roll_rows(y):
    return np.roll(y, -1, axis=0)


def wrap_pre(s):
    return lambda x: REF(np.asarray(s(np.asarray(x, dtype=np.float64)), dtype=np.float64)).astype(x.dtype)


def wrap_post(phi):
    return lambda x: np.asarray(phi(REF(x).astype(np.float64)), dtype=np.float64).astype(x.dtype)


def judge(kernel):
    bundle = gate.check(kernel, include_laws=False)
    full = gate.check(kernel, include_laws=True)
    return {
        "bundle_failed": bundle["declarative"][0],
        "reference_failed": bundle["reference"][0],
        "completed_failed": full["declarative"][0],
    }


def main():
    out = {"universal": [], "pre": {}, "post": {}}
    print("== (a) universal constructor: 24 arbitrary G, groups failed [bundle | reference | completed]")
    for seed in range(24):
        v = judge(factor(random_G(seed)))
        v["seed"] = seed
        v["kind"] = seed % 6
        out["universal"].append(v)
        print(f"  G#{seed:02d} kind={seed % 6}   {v['bundle_failed']}/9   {v['reference_failed']}/9   {v['completed_failed']}/9")
    admitted = sum(1 for v in out["universal"] if v["bundle_failed"] == 0)
    rejected_ref = sum(1 for v in out["universal"] if v["reference_failed"] > 0)
    rejected_full = sum(1 for v in out["universal"] if v["completed_failed"] > 0)
    print(f"  -> admitted by bundle {admitted}/24, rejected by reference {rejected_ref}/24, "
          f"rejected by completed bundle {rejected_full}/24")
    print()
    print("== (b) closure: reference wrapped by shift-class-respecting s (pre) / simplex-preserving Phi (post)")
    for name, s in [("scale_0.5", pre_scale(0.5)), ("scale_3", pre_scale(3.0)), ("negate", pre_negate),
                    ("permute_columns", pre_permute_columns), ("tanh_of_centered", pre_tanh_of_centered),
                    ("cube_of_centered", pre_cube_of_centered)]:
        v = judge(wrap_pre(s))
        out["pre"][name] = v
        print(f"  pre  {name:18s} {v['bundle_failed']}/9   {v['reference_failed']}/9   {v['completed_failed']}/9")
    for name, phi in [("smooth", post_smooth), ("reverse", post_reverse), ("square_renorm", post_square_renorm),
                      ("sqrt_renorm", post_sqrt_renorm), ("roll_rows", post_roll_rows)]:
        v = judge(wrap_post(phi))
        out["post"][name] = v
        print(f"  post {name:18s} {v['bundle_failed']}/9   {v['reference_failed']}/9   {v['completed_failed']}/9")
    (HERE / "results").mkdir(exist_ok=True)
    (HERE / "results" / "characterization.json").write_text(json.dumps(out, indent=2))


if __name__ == "__main__":
    main()
